  NSRect previous=NSZeroRect;NSUInteger index=0;for(NSButton *button in stack.arrangedSubviews){Check([button.title isEqual:titles[index]] && button.tag==(NSInteger)index && NSWidth(button.frame)>=310 && NSHeight(button.frame)>=28,@"each full label has its own normal-size action row");NSRect alignment=[button alignmentRectForFrame:button.frame];if(index){BOOL fits=!NSIntersectsRect(previous,alignment) && fabs(NSMinX(previous)-NSMinX(alignment))<1;if(!fits)fprintf(stderr,"Vertical choice geometry: previous=%s frame=%s alignment=%s\n",NSStringFromRect(previous).UTF8String,NSStringFromRect(button.frame).UTF8String,NSStringFromRect(alignment).UTF8String);Check(fits,@"vertical action alignment rectangles remain separate on old and new AppKit");}Check([stack hitTest:NSMakePoint(NSMidX(button.frame),NSMidY(button.frame))]==button,@"each action has a distinct clickable center");previous=alignment;index++;}
 }
